const norm = (s: string) =>
  s.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
    .replace(/[^a-z0-9 ]+/g, " ").replace(/\s+/g, " ").trim();

const INDICE = new Map<string, { nome: string; ufs: string[] }>();
for (const linha of RAW.split("\n")) {
  const [nome, uf] = linha.split("|");
  const k = norm(nome);
  const atual = INDICE.get(k);
  if (atual) atual.ufs.push(uf);
  else INDICE.set(k, { nome, ufs: [uf] });
}

const UFS = "ac|al|ap|am|ba|ce|df|es|go|ma|mt|ms|mg|pa|pb|pr|pe|pi|rj|rn|rs|ro|rr|sc|sp|se|to";

// DDD → UF. Serve pra desempatar: "Cedral" existe em SP e no MA.
const DDD_UF: Record<string, string> = {};
const faixa = (uf: string, ddds: number[]) => ddds.forEach((d) => { DDD_UF[String(d)] = uf; });
faixa("SP", [11, 12, 13, 14, 15, 16, 17, 18, 19]);
faixa("RJ", [21, 22, 24]); faixa("ES", [27, 28]);
faixa("MG", [31, 32, 33, 34, 35, 37, 38]);
faixa("PR", [41, 42, 43, 44, 45, 46]); faixa("SC", [47, 48, 49]);
faixa("RS", [51, 53, 54, 55]); faixa("DF", [61]); faixa("GO", [62, 64]);
faixa("TO", [63]); faixa("MT", [65, 66]); faixa("MS", [67]);
faixa("AC", [68]); faixa("RO", [69]); faixa("BA", [71, 73, 74, 75, 77]);
faixa("SE", [79]); faixa("PE", [81, 87]); faixa("AL", [82]); faixa("PB", [83]);
faixa("RN", [84]); faixa("CE", [85, 88]); faixa("PI", [86, 89]);
faixa("PA", [91, 93, 94]); faixa("AM", [92, 97]); faixa("RR", [95]);
faixa("AP", [96]); faixa("MA", [98, 99]);

export function ufDoTelefone(phone: string | null | undefined): string | null {
  const d = String(phone ?? "").replace(/\D/g, "");
  const local = d.startsWith("55") && d.length >= 12 ? d.slice(2) : d;
  return DDD_UF[local.slice(0, 2)] ?? null;
}

export type CidadeAchada = {
  nome: string;        // grafia oficial: "Valentim Gentil"
  uf: string;          // UF mais provável (a do DDD, se o município existir lá)
  /** Nome composto E no mesmo estado do DDD: é cidade, não nome de pessoa. */
  forte: boolean;
};

/**
 * A mensagem INTEIRA é o nome de um município? Aceita "sou de X", "X sp",
 * "cidade de X". Não procura cidade no meio de uma frase — isso geraria falso
 * positivo com sobrenome ("Marcos Sales").
 */
export function cidadeNaResposta(texto: string, phone?: string | null): CidadeAchada | null {
  let t = norm(texto || "");
  if (!t || t.split(" ").length > 7) return null;
  t = t
    .replace(/^(eu )?(sou|moro|falo|estou|to|fico|resido)( aqui)? (de|da|do|em|na|no) /, "")
    .replace(/^(aqui )?(de|da|do|em) /, "")
    .replace(/^(a |minha )?cidade( e| eh)?( de)? /, "")
    .replace(new RegExp(`( (${UFS}))$`), "")
    .trim();
  const achado = INDICE.get(t);
  if (!achado) return null;
  const ufDdd = ufDoTelefone(phone);
  const mesmaUf = !!ufDdd && achado.ufs.includes(ufDdd);
  return {
    nome: achado.nome,
    uf: mesmaUf ? ufDdd! : achado.ufs[0],
    forte: mesmaUf && t.includes(" "),
  };
}
